// Citizen product photos, grouped by category (folder under public/citizen/).
// Every image exists in two widths, generated by scripts/optimize-images.mjs:
//   /citizen/<path>.webp      up to 1600px
//   /citizen/<path>-640.webp  up to 640px

export const cSrc = (path: string) => `/citizen/${path}.webp`;
export const cSmall = (path: string) => `/citizen/${path}-640.webp`;

export const friedOnions = [
  { name: 'White — Fresh Fried',      img: cSmall('fried-onion/white-onion-fresh-fried') },
  { name: 'White — Dehydrated Fried', img: cSmall('fried-onion/white-onion-dehydrated-fried') },
  { name: 'White — Coated Fried',     img: cSmall('fried-onion/white-onion-coated-fried') },
  { name: 'Pink — Fresh Fried',       img: cSmall('fried-onion/pink-onion-fresh-fried') },
  { name: 'Pink — Dehydrated Fried',  img: cSmall('fried-onion/pink-onion-dehydrated-fried') },
  { name: 'Pink — Coated Fried',      img: cSmall('fried-onion/pink-onion-coated-fried') },
];

